mapper.select:
SELECT 
FROM appi_incident
WHERE org_id = #{orgId} AND id = #{incidentId}

SELECT 
FROM appi_incident
WHERE org_id = #{orgId}
ORDER BY detected_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM (
  SELECT 1
  FROM audit_log al
  LEFT JOIN workspace w ON w.id = al.workspace_id AND w.org_id = al.org_id
  WHERE al.org_id = #{orgId}
    AND al.created_at >= #{occurredFrom}
    AND al.created_at <= #{occurredTo}
  GROUP BY CASE WHEN w.id IS NULL THEN NULL ELSE al.workspace_id END,
    w.name, COALESCE(al.entity_type, 'system'), al.action, al.outcome
) incident_scope
